#p-home .hm-tip { margin: 0 0 -6px; font-size: 12px; color: var(--muted); display: flex; align-items: center; gap: 5px; flex: none; }   /* 홈 맨 위 한 줄 안내 */
#p-home .hm-tip svg { width: 13px; height: 13px; color: var(--accent); flex: none; }
